export function useZoomState(
  imageRect: ContainerRect,
  maxZoom: number,
  zoomWrapperRef?: React.RefObject<HTMLDivElement | null>,
) {
  const [zoom, setZoom] = React.useState(1);
  const [offsetX, setOffsetX] = React.useState(0);
  const [offsetY, setOffsetY] = React.useState(0);

  const animate = useZoomAnimation(zoom, offsetX, offsetY, zoomWrapperRef);

  const { currentSlide, globalIndex } = useLightboxState();
  const { containerRect, slideRect } = useController();
  const { minZoom, zoomInMultiplier } = useZoomProps();

  const currentSource = currentSlide && isImageSlide(currentSlide) ? currentSlide.src : undefined;
  const disabled = !currentSource || !zoomWrapperRef?.current;

  useLayoutEffect(() => {
    setZoom(1);
    setOffsetX(0);
    setOffsetY(0);
  }, [globalIndex, currentSource]);

  const changeOffsets = React.useCallback(
    (dx?: number, dy?: number, targetZoom?: number) => {
      const newZoom = targetZoom || zoom;

      const newOffsetX = offsetX - (dx || 0);
      const newOffsetY = offsetY - (dy || 0);

      const maxOffsetX = (imageRect.width * newZoom - slideRect.width) / 2 / newZoom;
      const maxOffsetY = (imageRect.height * newZoom - slideRect.height) / 2 / newZoom;

      setOffsetX(Math.min(Math.abs(newOffsetX), Math.max(maxOffsetX, 0)) * Math.sign(newOffsetX));
      setOffsetY(Math.min(Math.abs(newOffsetY), Math.max(maxOffsetY, 0)) * Math.sign(newOffsetY));
    },
    [zoom, offsetX, offsetY, slideRect, imageRect.width, imageRect.height],
  );

  const changeZoom = React.useCallback(
    (targetZoom: number, rapid?: boolean, dx?: number, dy?: number) => {
      const newZoom = round(
        targetZoom + 0.01 < maxZoom ? (targetZoom - 0.01 > minZoom ? targetZoom : minZoom) : maxZoom,
        5,
      );

      if (!rapid) {
        animate();
      }

      changeOffsets(dx ? dx * (1 / zoom - 1 / newZoom) : 0, dy ? dy * (1 / zoom - 1 / newZoom) : 0, newZoom);

      setZoom(newZoom);
    },
    [zoom, minZoom, maxZoom, changeOffsets, animate],
  );

  const handleControllerRectChange = useEventCallback(() => {
    if (zoom > 1) {
      if (zoom > maxZoom) {
        changeZoom(maxZoom, true);
      }

      changeOffsets();
    }
  });

  useLayoutEffect(handleControllerRectChange, [containerRect.width, containerRect.height, handleControllerRectChange]);

  const zoomIn = React.useCallback(() => {
    const targetZoom = zoom * zoomInMultiplier;
    changeZoom(zoom < 1 && targetZoom > 1 ? 1 : targetZoom);
  }, [zoom, zoomInMultiplier, changeZoom]);

  const zoomOut = React.useCallback(() => {
    const targetZoom = zoom / zoomInMultiplier;
    changeZoom(zoom > 1 && targetZoom < 1 ? 1 : targetZoom);
  }, [zoom, zoomInMultiplier, changeZoom]);

  return { zoom, offsetX, offsetY, disabled, changeOffsets, changeZoom, zoomIn, zoomOut };
}
import * as React from "react";

import { useEventCallback, useLightboxProps } from "../../../index.js";

export function useZoomCallback(zoom: number, disabled: boolean) {
  const { on } = useLightboxProps();

  const onZoomCallback = useEventCallback(() => {
    if (!disabled) {
      on.zoom?.({ zoom });
    }
  });

  React.useEffect(onZoomCallback, [zoom, onZoomCallback]);
}

import * as React from "react";

import {
  devicePixelRatio,
  ImageSlide,
  ImageSlideProps,
  ImageSource,
  isImageFitCover,
  SlideImage,
  UNKNOWN_ACTION_TYPE,
  useEventCallback,
  useLayoutEffect,
} from "../../index.js";

export type ResponsiveImageSlide = Omit<SlideImage, "srcSet"> & {
  srcSet: [ImageSource, ...ImageSource[]];
};

export function isResponsiveImageSlide(slide: SlideImage): slide is ResponsiveImageSlide {
  return (slide.srcSet?.length || 0) > 0;
}

export type ResponsiveImageProps = Omit<ImageSlideProps, "slide" | "rect"> &
  Required<Pick<ImageSlideProps, "rect">> & {
    slide: ResponsiveImageSlide;
    interactive: boolean;
  };

type ResponsiveImageState = {
  current?: string;
  preload?: string;
};

type ResponsiveImageStateAction = {
  type: "fetch" | "done";
  source: string;
};

function reducer(
  { current, preload }: ResponsiveImageState,
  { type, source }: ResponsiveImageStateAction,
): ResponsiveImageState {
  switch (type) {
    case "fetch":
      if (!current) {
        return { current: source };
      }
      return { current, preload: source };
    case "done":
      if (source === preload) {
        return { current: source };
      }
      return { current, preload };
    default:
      throw new Error(UNKNOWN_ACTION_TYPE);
  }
}

export function ResponsiveImage(props: ResponsiveImageProps) {
  const [{ current, preload }, dispatch] = React.useReducer(reducer, {});

  const { slide: image, rect, imageFit, render, interactive } = props;

  const srcSet = image.srcSet.sort((a, b) => a.width - b.width);
  const width = image.width ?? srcSet[srcSet.length - 1].width;
  const height = image.height ?? srcSet[srcSet.length - 1].height;
  const cover = isImageFitCover(image, imageFit);
  const maxWidth = Math.max(...srcSet.map((x) => x.width));
  const targetWidth = Math.min((cover ? Math.max : Math.min)(rect.width, width * (rect.height / height)), maxWidth);
  const pixelDensity = devicePixelRatio();

  const handleResize = useEventCallback(() => {
    const targetSource = srcSet.find((x) => x.width >= targetWidth * pixelDensity) ?? srcSet[srcSet.length - 1];

    if (!current || srcSet.findIndex((x) => x.src === current) < srcSet.findIndex((x) => x === targetSource)) {
      dispatch({ type: "fetch", source: targetSource.src });
    }
  });

  useLayoutEffect(handleResize, [rect.width, rect.height, pixelDensity, handleResize]);

  const handlePreload = useEventCallback((currentPreload: string) =>
    dispatch({ type: "done", source: currentPreload }),
  );

  const style = {
    // workaround occasional flickering in mobile Safari
    WebkitTransform: !interactive ? "translateZ(0)" : "initial",
  };

  if (!cover) {
    Object.assign(
      style,
      rect.width / rect.height < width / height ? { width: "100%", height: "auto" } : { width: "auto", height: "100%" },
    );
  }

  return (
    <>
      {preload && preload !== current && (
        <ImageSlide
          key="preload"
          {...props}
          // do not publish active slide status events
          offset={undefined}
          slide={{ ...image, src: preload, srcSet: undefined }}
          style={{ position: "absolute", visibility: "hidden", ...style }}
          onLoad={() => handlePreload(preload)}
          render={{
            ...render,
            iconLoading: () => null,
            iconError: () => null,
          }}
        />
      )}

      {current && (
        <ImageSlide key="current" {...props} slide={{ ...image, src: current, srcSet: undefined }} style={style} />
      )}
    </>
  );
}
  easing?: string;
};

/** Lightbox state update action */
export type LightboxStateUpdateAction = {
  type: "update";
  slides: readonly Slide[];
  index: number;
};

/** Lightbox state */
export interface LightboxState {
  /** lightbox slides */
  slides: readonly Slide[];
  /** current slide index */
  currentIndex: number;
  /** current slide index in the (-∞, +∞) range */
  globalIndex: number;
  /** current slide */
  currentSlide: Slide | undefined;
  /** current animation */
  animation?: { increment?: number; duration?: number; easing?: string };
}

/** Render function */
export type RenderFunction<T = void> = [T] extends [void] ? () => React.ReactNode : (props: T) => React.ReactNode;

/** `render.slide` render function props */
export interface RenderSlideProps<S extends Slide = Slide> {
  /** slide */
  slide: S;
  /** slide offset (`0` - current slide, `1` - next slide, `-1` - previous slide, etc.) */
  offset: number;
  /** container rect */
  rect: ContainerRect;
}

/** `render.slideHeader` render function props */
export interface RenderSlideHeaderProps {
  slide: Slide;
}

/** `render.slideFooter` render function props */
export interface RenderSlideFooterProps {
  slide: Slide;
}

/** `render.slideContainer` render function props */
export interface RenderSlideContainerProps extends React.PropsWithChildren {
  slide: Slide;
}

/** Custom render functions. */
export interface Render {
  /** render custom slide type, or override the default image slide */
  slide?: RenderFunction<RenderSlideProps>;
  /** render custom slide header (use absolute positioning) */
  slideHeader?: RenderFunction<RenderSlideHeaderProps>;
  /** render custom slide footer (use absolute positioning) */
  slideFooter?: RenderFunction<RenderSlideFooterProps>;
  /** render custom slide container */
  slideContainer?: RenderFunction<RenderSlideContainerProps>;
  /** render custom controls or additional elements in the lightbox (use absolute positioning) */
  controls?: RenderFunction;
  /** render custom Prev icon */
  iconPrev?: RenderFunction;
  /** render custom Next icon */
  iconNext?: RenderFunction;
  /** render custom Close icon */
  iconClose?: RenderFunction;
  /** render custom Loading icon */
import { Augmentation, Component, Module, Node, Plugin } from "./types.js";
import { MODULE_CONTROLLER } from "./consts.js";

export function createModule(name: string, component: Component): Module {
  return { name, component };
}

export function createNode(module: Module, children?: Node[]): Node {
  return { module, children };
}

function traverseNode(node: Node, target: string, apply: (node: Node) => Node[] | undefined): Node[] | undefined {
  if (node.module.name === target) {
    return apply(node);
  }
  if (node.children) {
    return [
      createNode(
        node.module,
        node.children.flatMap((n) => traverseNode(n, target, apply) ?? []),
      ),
    ];
  }
  return [node];
}

function traverse(nodes: Node[], target: string, apply: (node: Node) => Node[] | undefined): Node[] {
  return nodes.flatMap((node) => traverseNode(node, target, apply) ?? []);
}

export function withPlugins(
  root: Node[],
  plugins: readonly Plugin[] = [],
  augmentations: Augmentation[] = [],
): { config: Node[]; augmentation: Augmentation } {
  let config = root;

  const contains = (target: string) => {
    const nodes = [...config];
    while (nodes.length > 0) {
      const node = nodes.pop();
      if (node?.module.name === target) return true;
      if (node?.children) nodes.push(...node.children);
    }
    return false;
  };

  const addParent = (target: string, module: Module) => {
    if (target === "") {
      config = [createNode(module, config)];
      return;
    }
    config = traverse(config, target, (node) => [createNode(module, [node])]);
  };

  const append = (target: string, module: Module) => {
    config = traverse(config, target, (node) => [createNode(node.module, [createNode(module, node.children)])]);
  };

  const addChild = (target: string, module: Module, precede?: boolean) => {
    config = traverse(config, target, (node) => [
      createNode(node.module, [
        ...(precede ? [createNode(module)] : []),
        ...(node.children ?? []),
        ...(!precede ? [createNode(module)] : []),
      ]),
    ]);
  };

  const addSibling = (target: string, module: Module, precede?: boolean) => {
    config = traverse(config, target, (node) => [
      ...(precede ? [createNode(module)] : []),
      node,
      ...(!precede ? [createNode(module)] : []),
    ]);
  };

  const addModule = (module: Module) => {
    append(MODULE_CONTROLLER, module);
  };

  const replace = (target: string, module: Module) => {
    config = traverse(config, target, (node) => [createNode(module, node.children)]);
  };

  const remove = (target: string) => {
    config = traverse(config, target, (node) => node.children);
  };

  const augment = (augmentation: Augmentation) => {
    augmentations.push(augmentation);
  };

  plugins.forEach((plugin) => {
    plugin({
      contains,
      addParent,
      append,
      addChild,
      addSibling,
      addModule,
      replace,
      remove,
      augment,
    });
  });

  return {
    config,
    augmentation: (props) => augmentations.reduce((acc, augmentation) => augmentation(acc), props),
  };
}

